from typing import Any, Dict


class StorageRequest:
    def __init__(self, data: Any, content_type: str = 'application/octet-stream'):
        self.data = data
        self.content_type = content_type


class StorageResponse:
    def __init__(self, data: Dict):
        self.data = data


def normalize_payload(payload: Dict) -> StorageRequest:
    return StorageRequest(payload['data'], payload.get('content_type', 'application/octet-stream'))


def normalize_response(response: Dict) -> StorageResponse:
    return StorageResponse(response)

from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
from azure.ai.vision.image_analysis import ImageAnalysisClient
from azure.ai.vision.image_analysis.models import VisualFeatures



def run_ocr_on_stored_document(config, object_name):
    with DefaultAzureCredential() as credential:
        storage_client = BlobServiceClient(config['account_url'], credential=credential)
        blob = storage_client.get_blob_client(container=config['container'], blob=object_name)
        image_data = blob.download_blob().readall()

        vision_client = ImageAnalysisClient(endpoint=config['vision_endpoint'], credential=credential)
        result = vision_client.analyze(image_data=image_data, visual_features=[VisualFeatures.READ])

        if result.read_result:
            return {'text': result.read_result.text}
        else:
            return {'error': 'OCR failed'}

from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
from azure.ai.translation.document import DocumentTranslationClient
from azure.ai.translation.document.models import DocumentTranslationInput



def translate_stored_text(config, object_name, target_language):
    with DefaultAzureCredential() as credential:
        storage_client = BlobServiceClient(config['account_url'], credential=credential)
        blob = storage_client.get_blob_client(container=config['container'], blob=object_name)
        image_data = blob.download_blob().readall()

        translation_client = DocumentTranslationClient(endpoint=config['translation_endpoint'], credential=credential)
        input = DocumentTranslationInput(source_url=blob.url, target_language_code=target_language)
        result = translation_client.translate_document(input)

        if result.status == 'Succeeded':
            return {'translated_text': result.translated_document_url}
        else:
            return {'error': 'Translation failed'}

from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
from azure.ai.textanalytics import TextAnalyticsClient



def summarize_stored_asset(config, object_name):
    with DefaultAzureCredential() as credential:
        storage_client = BlobServiceClient(config['account_url'], credential=credential)
        blob = storage_client.get_blob_client(container=config['container'], blob=object_name)
        image_data = blob.download_blob().readall()

        text_analytics_client = TextAnalyticsClient(endpoint=config['text_analytics_endpoint'], credential=credential)
        result = text_analytics_client.summarize(documents=[image_data])

        if result[0].sentences:
            return {'summary': ' '.join([sentence.text for sentence in result[0].sentences])}
        else:
            return {'error': 'Summarization failed'}

from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
from azure.ai.textanalytics import TextAnalyticsClient



def embed_asset_metadata_and_text(config, object_name):
    with DefaultAzureCredential() as credential:
        storage_client = BlobServiceClient(config['account_url'], credential=credential)
        blob = storage_client.get_blob_client(container=config['container'], blob=object_name)
        image_data = blob.download_blob().readall()

        text_analytics_client = TextAnalyticsClient(endpoint=config['text_analytics_endpoint'], credential=credential)
        result = text_analytics_client.extract_key_phrases(documents=[image_data])

        if result[0].key_phrases:
            return {'key_phrases': result[0].key_phrases}
        else:
            return {'error': 'Key phrase extraction failed'}
